# Generated by manage.py generate_test_cases.
from playwright.sync_api import expect
from bloomerp.tests.models.communication.voip.fixtures import VoIPFixtures
from bloomerp.tests.base import BloomerpE2ETestCase, E2EAction, E2ERequestScenario


class TestReconfigureVoIpconnectionViewE2E(VoIPFixtures, BloomerpE2ETestCase):
    """Exercise secret-preserving reconfiguration through the connection's detail tab."""

    view_name = "reconfigure_voip_connection"

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Save provider settings in a real browser and return to the connection detail."""
        self.prepare_voip()
        return [
            E2ERequestScenario(
                name="Reconfigure an existing carrier connection",
                user=self.admin_user,
                url=self.connection.get_absolute_url(),
                actions=[
                    E2EAction(
                        name="Update settings with blank secrets",
                        execute=self.reconfigure,
                        validators=self.verify_saved,
                    )
                ],
            )
        ]

    def reconfigure(self) -> None:
        """Open the detail tab and submit a new name without exposing credentials."""
        expect(
            self.page.locator('[bloomerp-component="bloomerp:messaging-panel"]')
        ).to_have_attribute("data-component-initialized", "true")
        self.page.get_by_role(
            "tab", name="Reconfigure connection", exact=True
        ).click()
        expect(self.page.locator('input[name="auth_token"]')).to_have_value("")
        self.page.locator('#voip-reconfigure-form input[name="name"]').fill(
            "Updated carrier"
        )
        self.page.get_by_role("button", name="Save configuration").click()

    def verify_saved(self) -> None:
        """Confirm the same account changed while secrets were retained."""
        expect(
            self.page.get_by_text("Updated carrier", exact=True).first
        ).to_be_visible()
        self.connection.refresh_from_db()
        self.assertEqual(
            self.connection.get_credentials()["auth_token"], "test-auth-token"
        )
        self.assertEqual(self.connection.status, "draft")
